create or replace view KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_VIEW.V_ARTBEW_MO_EK_CP_SUM(
	MANDANT_ID COMMENT 'Mandant im DWH',
	ART_ID COMMENT 'Input: Artikel - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1',
	BEWART_ID COMMENT 'Bewegungsart ID. Bewegungsarten > 1000 beziehen sich auf Warenausgang, < 1000 auf Wareneingang',
	BEWART_DET_ID COMMENT 'Detaillierte Bewegungsart zum Aufbruch der bestehenden bewart_id',
	WUP_ID COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	GP_ID COMMENT 'Geschäftspartner - ID (Lieferanten - ID).Lieferant des Artikel-Markt innerhalb des Monats gem. Lieferantenfindung dbp_data.artbew_dat_ek_cp_sum.',
	KJMO COMMENT 'Monat eines Kalenderjahres, Format JJJJMM',
	WRG_ID COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	WUP_BEREINIGT_FG COMMENT 'Flag: Zeigt ob die Kennzahlen für diesen Markt in die \""bereinigte\"" Sicht einfließen dürfen, d.h. der Markt hatte in den letzten 12 Monaten vor dem Wochenbeginn der aktuellen Auwertung geöffnet und wird in der betrachteten Woche nicht permanent geschlossen (zieht höchstens um).',
	POSTEN_ID COMMENT 'Postenkennzeichen. Für Artikel, die nicht staendig im Sortiment sind. Angereichert jeweils aktuell aus dem historisierten Artikelstamm art_per.Wird für den Split der Wochenebene in Aggregat benötigt.',
	ZEK_ID COMMENT 'Zentraleinkäufer - ID: Diese ID ist nicht mit der Mitarbeiter - ID identisch',
	EIGENMARKE_FG COMMENT 'Flag Eigenmarke (wenn zek_id (Verhandler) und zek_vat_id (Verantwortlicher) in der Tabelle art nicht identisch sind, wird das Flag auf 1 gesetzt (Eigenmarke-Artikel))',
	UMSATZ_NETTO COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag',
	UMSATZ_NETTO_VJ COMMENT 'Vorjahreswert - Umsatz vermindert um den Mehrwertsteuerbetrag ',
	BETRAG_KMEP COMMENT 'Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) ergibt sich aus der Differenz von EK4N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale in diesem Kalendermonat. Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise des Kalendermonats herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	BETRAG_KMEP_VJ COMMENT 'Vergleichswert des Vorjahres - Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) ergibt sich aus der Differenz von EK4N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale in diesem Kalendermonat. Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise des Kalendermonats herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	BETRAG_KMEP_O_FWU COMMENT 'Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) ohne Festwertumlage ergibt sich aus der Differenz von EK3N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale in diesem Kalendermonat. Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise des Kalendermonats herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	BETRAG_KMEP_O_FWU_VJ COMMENT 'Vergleichswert des Vorjahres - Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) ohne Festwertumlage ergibt sich aus der Differenz von EK3N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale in diesem Kalendermonat. Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise des Kalendermonats herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	LOGKOSTENZUSCHLAG COMMENT 'Logistikkostenzuschlag (ein kalkulierter Wert, der bei zentraler Lieferung Bestandteil einiger Einstandspreise ist)',
	LOGKOSTENZUSCHLAG_VJ COMMENT 'Vorjahreswert - Logistikkostenzuschlag (ein kalkulierter Wert, der bei zentraler Lieferung Bestandteil einiger Einstandspreise ist)',
	WERBE_ABSCHRIFT_NETTO COMMENT 'Marktabschriften durch Werbung (netto- vermindert um den Mehrwertsteuerbetrag)',
	WERBE_ABSCHRIFT_NETTO_VJ COMMENT 'Vorjahreswert - Marktabschriften durch Werbung (netto- vermindert um den Mehrwertsteuerbetrag)',
	PREIS_ABSCHRIFT_NETTO COMMENT 'Preisabschrift DE: marktabschriften (abschriftart_id in (5,7); KMO:Filterung art_umbewertung wie folgt: Mandant 2,5: preis_aend_grund_id in (7,10); Mandant 3: preis_aend_grund_id =11; Mandant 6: preis_aend_grund_id =2; Mandant 7,8: preis_aend_grund_id =7',
	PREIS_ABSCHRIFT_NETTO_VJ COMMENT 'Preisabschr.VJ DE: marktabschriften (abschriftart_id in (5,7); KMO:Filterung art_umbewertung wie folgt: Mandant 2,5: preis_aend_grund_id in (7,10); Mandant 3: preis_aend_grund_id =11; Mandant 6: preis_aend_grund_id =2; Mandant 7,8: preis_aend_grund_id =7',
	UMRECHNUNGSKURS_HIST COMMENT 'Historischer Berichtskurs aus dbp_data.kurs ',
	BETRAG_KMEP_INV_NETTO_KM COMMENT 'Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) für die Inventur innerhalb Warenbewegungen ergibt sich aus der Differenz von EK4N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale an diesem Tag. Die Absatzmenge menge_lagerbew_bme aus lagerbew_det mit lager_bewart_id in (701,702,711,712,V30,V31,V32,V33,V35,V36,V37,V38,V45,V50,V54,W00,W02,W05,W10,W12,W15,W16,W17,W25,W27,W30).Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise der Kalenderwoche herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).'
) as 
    SELECT 
        mandant_id,
        art_id,
        bewart_id,
        bewart_det_id,
        wup_id,
        nb_id,
        gp_id,
        kjmo,
        wrg_id,
        wup_bereinigt_fg,
        posten_id,
        zek_id,
        eigenmarke_fg,
        umsatz_netto,
        umsatz_netto_vj,
        betrag_kmep,
        betrag_kmep_vj,
        betrag_kmep_o_fwu,
        betrag_kmep_o_fwu_vj,
        logkostenzuschlag,
        logkostenzuschlag_vj,
        werbe_abschrift_netto,
        werbe_abschrift_netto_vj,
        preis_abschrift_netto,
        preis_abschrift_netto_vj,
        umrechnungskurs_hist,
        betrag_kmep_inv_netto_km

FROM DBP_DATA.ARTBEW_MO_EK_CP_SUM ;
